#include "protocol.h"
#include <algorithm>
#include <chrono>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include "engine.h"
#include "notation.h"
#include "perft.h"
namespace rpsc { namespace {
const char* item_name(int b){return b==0?"Pu":b==1?"Ro":"St";}
bool parse_side(const std::string&s,Color&c){if(s=="W"){c=Color::White;return true;}if(s=="B"){c=Color::Black;return true;}return false;}
void parse_limits(std::istringstream&in,SearchLimits&l){std::string k;while(in>>k){if(k=="depth")in>>l.depth;else if(k=="movetime"){long long ms;in>>ms;l.movetime=std::chrono::milliseconds(ms);l.depth=84;}else if(k=="nodes")in>>l.nodes;else if(k=="multipv")in>>l.multipv;}}
void print_search(const Position&pos,const SearchResult&r){if(!r.has_move){std::cout<<"bestmove (none)\n";return;}auto ms=std::max<std::int64_t>(1,r.elapsed.count());auto nps=r.nodes*1000ULL/static_cast<std::uint64_t>(ms);bool white=pos.side_to_move()==Color::White;if(!r.lines.empty()){for(std::size_t i=0;i<r.lines.size();++i){auto&ln=r.lines[i];Value v=white?ln.value:-ln.value;std::cout<<"info multipv "<<i+1<<" depth "<<r.depth<<" seldepth "<<r.seldepth<<" nodes "<<r.nodes<<" nps "<<nps<<" score "<<std::fixed<<std::setprecision(2)<<double(v)/ScoreUnit;if(!ln.pv.empty())std::cout<<" pv "<<format_pv(pos,ln.pv);std::cout<<"\n";}}else{Value v=white?r.value:-r.value;std::cout<<"info depth "<<r.depth<<" seldepth "<<r.seldepth<<" nodes "<<r.nodes<<" nps "<<nps<<" score "<<std::fixed<<std::setprecision(2)<<double(v)/ScoreUnit;if(!r.pv.empty())std::cout<<" pv "<<format_pv(pos,r.pv);std::cout<<"\n";}std::cout<<"bestmove "<<format_move(r.best_move)<<"\n";}
}
int run_protocol(){Engine e;std::cout<<"RPSC Engine 0.14.0\n";std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);std::string cmd;in>>cmd;if(cmd=="quit"||cmd=="exit")break;if(cmd=="rpsc"){std::cout<<"id name RPSC Engine 0.14\nid author Jungwoo Kim\nrpscok\n";}else if(cmd=="isready")std::cout<<"readyok\n";else if(cmd=="newgame"||line=="position startpos"){e.new_game();std::cout<<"ok\n";}else if(cmd=="clear"){e.clear_search();std::cout<<"ok\n";}else if(cmd=="items"){std::string s;int p,r,st;Color c;if(!(in>>s>>p>>r>>st)||!parse_side(s,c)||p<0||r<0||st<0)std::cout<<"error invalid items\n";else{e.position().set_items(c,p,r,st);std::cout<<"ok\n";}}else if(cmd=="gain"){std::string s,it;Color c;if(!(in>>s>>it)||!parse_side(s,c)||(it!="Pu"&&it!="Ro"&&it!="St"))std::cout<<"error invalid gain\n";else{auto a=e.position().items(c);int b=it=="Pu"?0:it=="Ro"?1:2;++a[b];e.position().set_items(c,a[0],a[1],a[2]);std::cout<<"ok\n";}}else if(cmd=="side"){std::string s;Color c;if(!(in>>s)||!parse_side(s,c))std::cout<<"error invalid side\n";else{e.position().set_side_to_move(c);std::cout<<"ok\n";}}else if(cmd=="match"){int w,b,rem;if(!(in>>w>>b>>rem)||w<0||b<0||rem<-1)std::cout<<"error invalid match context\n";else{e.position().set_match_context(w,b,rem);std::cout<<"ok\n";}}else if(cmd=="show"||cmd=="d")std::cout<<e.position().debug_string();else if(cmd=="legal")std::cout<<generate_legal_moves(e.position()).size()<<"\n";else if(cmd=="moves")std::cout<<generate_search_moves_info(e.position()).size()<<"\n";else if(cmd=="perft"){int d;in>>d;std::cout<<"perft "<<d<<" "<<e.perft(d)<<"\n";}else if(cmd=="move"){std::string rest;std::getline(in,rest);if(!rest.empty()&&rest[0]==' ')rest.erase(0,1);Move m;if(!parse_move(e.position(),rest,m))std::cout<<"error illegal move\n";else{UndoState u;e.position().do_move(m,u);std::cout<<"ok\n";}}else if(cmd=="go"){SearchLimits l;l.depth=8;parse_limits(in,l);print_search(e.position(),e.go(l));}else if(cmd=="chooseitem"){std::string s;Color chooser;if(!(in>>s)||!parse_side(s,chooser)){std::cout<<"error invalid chooseitem\n";continue;}SearchLimits l;l.depth=8;parse_limits(in,l);auto ch=e.choose_item(chooser,l);for(std::size_t i=0;i<ch.lines.size();++i){auto&x=ch.lines[i];Value v=chooser==Color::White?x.white_value:-x.white_value;std::cout<<"info item "<<i+1<<" "<<item_name(x.bucket)<<" score "<<std::fixed<<std::setprecision(2)<<double(v)/ScoreUnit<<" depth "<<x.probe.depth<<" nodes "<<x.probe.nodes<<"\n";}std::cout<<"bestitem "<<(ch.best_bucket>=0?item_name(ch.best_bucket):"(none)")<<"\n";}else if(cmd=="chooseinitial"){SearchLimits l;l.depth=8;parse_limits(in,l);auto ch=e.choose_initial(l);for(std::size_t i=0;i<ch.lines.size();++i){auto&x=ch.lines[i];std::cout<<"info initial "<<i+1<<" "<<(x.choose_first?"first":"second")<<" "<<item_name(x.bucket)<<" score "<<std::fixed<<std::setprecision(2)<<double(x.chooser_value)/ScoreUnit<<" depth "<<x.probe.depth<<" nodes "<<x.probe.nodes<<"\n";}std::cout<<"bestinitial "<<(ch.choose_first?"first":"second")<<" "<<(ch.best_bucket>=0?item_name(ch.best_bucket):"(none)")<<"\n";}else if(cmd=="bench"){e.new_game();SearchLimits l;l.depth=4;auto r=e.go(l);std::cout<<"bench depth 4 nodes "<<r.nodes<<" time "<<r.elapsed.count()<<" ms bestmove "<<(r.has_move?format_move(r.best_move):"(none)")<<"\n";}else if(cmd=="help")std::cout<<"newgame | items W/B pu ro st | gain W/B Pu/Ro/St | match Wquiz Bquiz remainingPlies | side W/B | move NOTATION | go depth N | go movetime MS [multipv N] | chooseitem W/B | chooseinitial | legal | moves | perft N | bench | show | clear | quit\n";else std::cout<<"error unknown command\n";}return 0;}
} // namespace rpsc
